(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.YamaAppLinks=api;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
  'use strict';
  const links={chat:[['chat-web','Otevřít Yamachat na webu','https://yamachat.eu/yamachat.html'],['chat-download','Stažení Yamachatu','https://yamachat.eu/download/']],search:[['search-android','Android APK','https://updates.yamachat.eu/yamasearch/YamaSearch-Android-latest.apk'],['search-ios','iPhone / iPad PWA','https://yamachat.eu/yamasearch/'],['search-installer','Windows instalátor','https://updates.yamachat.eu/yamasearch/YamaSearch-Setup-latest.exe'],['search-portable','Windows portable','https://updates.yamachat.eu/yamasearch/YamaSearch-Portable-latest.zip']],help:[['help-installer','Windows instalátor','https://updates.yamachat.eu/yamahelp/YamaHelp-Setup-latest.exe'],['help-portable','Windows portable','https://updates.yamachat.eu/yamahelp/YamaHelp-Portable-latest.zip']],view:[['view-installer','Windows instalátor 1.6.8','https://updates.yamachat.eu/yamaview/YamaView-Setup-1.6.8.exe'],['view-portable','Windows portable 1.6.8','https://updates.yamachat.eu/yamaview/YamaView-Portable-1.6.8.zip'],['view-android','Android APK 1.6.8','https://updates.yamachat.eu/yamaview/YamaView-Android-1.6.8.apk']]};
  links.convert=[['convert-android','Stáhnout Android APK','https://updates.yamachat.eu/yamaconvert/YamaConvert-Android-latest.apk'],['convert-android-pwa','Otevřít Android PWA','https://yamachat.eu/yamaconvert/'],['convert-windows','Instalátor pro Windows (.exe)','https://updates.yamachat.eu/yamaconvert/YamaConvert-Setup-latest.exe'],['convert-windows-portable','Windows portable (.zip)','https://updates.yamachat.eu/yamaconvert/YamaConvert-Portable-latest.zip']];
  function verified(report,id,now=Date.now()){
    const checked=Date.parse(report?.checkedAt);if(!Number.isFinite(checked)||now<checked||now-checked>7*86400000)return [];
    return (links[id]||[]).filter(([key,,url])=>report.results?.some(result=>{const verifiedAt=Date.parse(result.verifiedAt||report.checkedAt);return result.id===key&&result.url===url&&result.available===true&&result.status===200&&Number.isFinite(verifiedAt)&&now>=verifiedAt&&now-verifiedAt<=7*86400000;})).map(([,label,url])=>({label,url}));
  }
  function markup(report,id){if(id==='yamaportal')return '<div class="app-actions"><a class="secondary" href="https://yamachat.eu/" target="_blank" rel="noopener noreferrer">Otevřít web / PWA ↗</a><button class="secondary" type="button" data-portal-route="stazeni">Windows a PWA ke stažení →</button><button class="secondary" type="button" data-portal-route="aktualizace">Historie aktualizací →</button></div><p class="caption">Instalátor a portable verze se nabízejí jen při potvrzené dostupnosti.</p>';const actions=id==='convert'?links.convert.map(([,label,url])=>({label,url})):verified(report,id);const note=id==='convert'?'Pro stahování z veřejných sociálních odkazů použij aplikaci. Android APK stahuje přímo v telefonu; Windows aplikace běží místně v počítači. Web a PWA zůstávají pro převod souborů v zařízení. Instalátor vytvoří zástupce; přenosnou ZIP verzi rozbal a spusť Start-YamaConvert.cmd.':id==='view'?'YamaView 1.6.8 je nahraný pro Windows jako instalátor i portable ZIP a pro Android jako APK. Vydání uvádí automatické přihlášení přes YamaPortal, návrat do aplikace a výchozí Yama server pro obě platformy. Fyzický Android ani vzdálené spojení jsme zde samostatně neověřili.':'Instalátor i portable jsou určené pro Windows.';const native=typeof YamaNativeUI!=="undefined"?YamaNativeUI.markup(id):"";return actions.length||native?`<div class="app-actions">${native}${actions.map(action=>`<a class="secondary" href="${action.url}" target="_blank" rel="noopener noreferrer">${action.label} ↗</a>`).join('')}</div><p class="caption">${note}</p>`:'';}
  return {verified,markup};
});
